# Generated by manage.py generate_test_cases.
"""Cover native submission and safe markup for the searchable choice widget."""

from typing import Any

from django.http import QueryDict

from bloomerp.tests.base import BloomerpWidgetTestCase, WidgetOperation, WidgetScenario
from bloomerp.widgets.choice_widget import ChoiceWidget


class TestChoiceWidget(BloomerpWidgetTestCase[ChoiceWidget]):
    """Exercise single and multiple choices without database fixtures."""

    widget_class = ChoiceWidget

    def _render(self, widget: ChoiceWidget) -> str:
        """Render grouped choices with selected values and ordinary field attributes."""
        return widget.render("status", ["a", "b"], attrs={"id": "id_status", "disabled": True})

    def _markup(self, value: Any) -> bool:
        """Check native fallback, safe labels, groups, and component initialization."""
        return all(fragment in value for fragment in (
            'bloomerp-component="choice-widget"', 'name="status"',
            'id="id_status"', 'disabled', 'multiple', '<optgroup label="Group">',
            'value="a" selected', 'value="b" selected', '&lt;Alpha&gt;',
        )) and '<Alpha>' not in value

    def _submit(self, widget: ChoiceWidget) -> Any:
        """Extract repeated submitted keys using Django's native scalar/list contract."""
        return widget.value_from_datadict(QueryDict("status=a&status=b"), {}, "status")

    def _empty(self, widget: ChoiceWidget) -> Any:
        """Extract an absent field after all selections have been cleared."""
        return widget.value_from_datadict(QueryDict(), {}, "status")

    def _single(self, value: Any) -> bool:
        """Require the last submitted scalar for single-choice fields."""
        return value == "b"

    def _multiple(self, value: Any) -> bool:
        """Require both values for multiple-choice fields."""
        return value == ["a", "b"]

    def _empty_multiple(self, value: Any) -> bool:
        """Require an empty list when multiple choices are cleared."""
        return value == []

    def get_test_scenarios(self) -> list[WidgetScenario[ChoiceWidget]]:
        """Cover both configuration styles, escaped rendering, and cleared submission."""
        return [
            WidgetScenario(name="Single choice submits a scalar", operations=[
                WidgetOperation(name="Submit", execute=self._submit, result_validators=self._single),
            ]),
            WidgetScenario(name="Multiple choice preserves native semantics", constructor_kwargs={
                "allow_multiple": True, "choices": [("Group", [("a", "<Alpha>"), ("b", "Beta")])],
            }, operations=[
                WidgetOperation(name="Render", execute=self._render, result_validators=self._markup),
                WidgetOperation(name="Submit", execute=self._submit, result_validators=self._multiple),
                WidgetOperation(name="Clear", execute=self._empty, result_validators=self._empty_multiple),
            ]),
            WidgetScenario(name="Attributes can enable multiple selection", constructor_kwargs={
                "attrs": {"allow_multiple": True},
            }, operations=[
                WidgetOperation(name="Submit", execute=self._submit, result_validators=self._multiple),
            ]),
        ]
